using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: invalid input tests ---

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Tax rate below zero")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above one")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> DiscountTestCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m, "No discount" };
            yield return new object[] { 100.00m, 10m, 90.00m, "10% off" };
            yield return new object[] { 100.00m, 50m, 50.00m, "Half off" };
            yield return new object[] { 100.00m, 100m, 0.00m, "Full discount" };
            yield return new object[] { 49.99m, 25m, 37.4925m, "Fractional result" };
            yield return new object[] { 0.00m, 50m, 0.00m, "Zero price" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // --- ApplyDiscount: boundary/error cases ---

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Discount below 0%")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRange(double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(50m, (decimal)discountPercent));
    }

    // --- FormatPrice: DynamicData from method ---

    public static IEnumerable<object[]> FormatPriceTestCases()
    {
        yield return new object[] { 19.99m, "$", "$19.99" };
        yield return new object[] { 19.99m, "€", "€19.99" };
        yield return new object[] { 0.50m, "£", "£0.50" };
        yield return new object[] { 1000m, "$", "$1000.00" };
    }

    [TestMethod]
    [DynamicData(nameof(FormatPriceTestCases), DynamicDataSourceType.Method)]
    public void FormatPrice_VariousCurrencies_ReturnsFormattedString(
        decimal price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice(price, symbol);

        Assert.AreEqual(expected, result);
    }
}

